:root {
  --ink: #0a0b13;
  --paper: #f8ead9;
  --orange: #ff8a3d;
  --orange-hot: #ff5f2e;
  --pink: #ff2f86;
  --cyan: #3de7ff;
  --lime: #b9ff66;
  --gold: #ffd35a;
  --violet: #281d4d;
  --hud-line: rgba(255, 242, 223, 0.26);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0b13;
  color: var(--paper);
  font-family: "Rajdhani", "Arial Narrow", sans-serif;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

body { position: fixed; inset: 0; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #0a0b13;
}

#game-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
}

#grade,
#scanlines,
#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

#grade {
  background:
    radial-gradient(120% 90% at 72% 18%, rgba(255, 114, 54, 0.09), transparent 46%),
    linear-gradient(180deg, rgba(11, 8, 30, 0.22), transparent 27%, transparent 65%, rgba(6, 8, 22, 0.36));
  mix-blend-mode: normal;
}

#scanlines {
  opacity: 0.075;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.12) 0, rgba(255, 255, 255, 0.12) 1px, transparent 1px, transparent 4px);
}

#vignette {
  background: radial-gradient(ellipse at center, transparent 52%, rgba(4, 5, 12, 0.32) 79%, rgba(2, 3, 8, 0.7) 100%);
}

.is-hidden { display: none !important; }

/* ============ HUD ============ */

#hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.4s ease;
}

.hud-top-left {
  position: absolute;
  top: calc(24px + var(--safe-top));
  left: calc(28px + var(--safe-left));
  display: flex;
  flex-direction: column;
  gap: 17px;
}

.brand-small { display: flex; align-items: center; gap: 10px; opacity: 0.95; }

.brand-mark {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 216, 180, 0.55);
  color: var(--orange);
  font-family: "Bebas Neue", sans-serif;
  font-size: 23px;
  transform: skew(-7deg);
  background: rgba(10, 9, 22, 0.4);
}

.brand-copy {
  font-size: 8.5px;
  letter-spacing: 0.28em;
  line-height: 1.2;
  color: rgba(255, 240, 224, 0.72);
}

.brand-copy b { color: #fff6e9; letter-spacing: 0.32em; }

.mission-card {
  width: 280px;
  padding: 13px 15px 12px;
  border-left: 2px solid var(--orange);
  background: linear-gradient(90deg, rgba(10, 9, 22, 0.82), rgba(10, 9, 22, 0.28) 82%, transparent);
  clip-path: polygon(0 0, 100% 0, calc(100% - 13px) 100%, 0 100%);
  backdrop-filter: blur(5px);
}

.mission-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--orange);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 9px var(--orange);
  animation: pulse 1.6s ease-in-out infinite;
}

@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.35; transform: scale(0.75); } }

.mission-title {
  margin-top: 4px;
  font-family: "Bebas Neue", sans-serif;
  font-size: 25px;
  line-height: 1;
  letter-spacing: 0.05em;
  color: #fff8ec;
  text-shadow: 0 2px 16px rgba(0, 0, 0, 0.4);
}

.mission-objective {
  margin-top: 5px;
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 239, 222, 0.76);
  letter-spacing: 0.045em;
}

.mission-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(255, 220, 182, 0.55);
}

.mission-meta #mission-distance { color: var(--gold); }
.mission-sep { color: rgba(255, 255, 255, 0.25); }

.hud-top-center {
  position: absolute;
  top: calc(23px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.wanted { display: flex; gap: 3px; color: rgba(255, 247, 230, 0.16); font-size: 18px; text-shadow: 0 0 9px transparent; transition: color 0.25s; }
.wanted .star.on { color: var(--gold); text-shadow: 0 0 12px rgba(255, 196, 65, 0.78); }
.wanted .star.flash { animation: starflash 0.6s steps(2, end) infinite; }
@keyframes starflash { 50% { opacity: 0.28; } }

.district {
  color: rgba(255, 239, 219, 0.62);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.6);
}

.hud-top-right {
  position: absolute;
  top: calc(24px + var(--safe-top));
  right: calc(30px + var(--safe-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}

.cash {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 5px 0 5px 20px;
  border-bottom: 1px solid rgba(255, 227, 192, 0.28);
}

.cash-label { font-size: 8px; letter-spacing: 0.25em; color: rgba(255, 234, 205, 0.58); }
.cash-value {
  font-family: "Bebas Neue", sans-serif;
  font-size: 33px;
  line-height: 0.9;
  letter-spacing: 0.04em;
  color: var(--lime);
  text-shadow: 0 0 20px rgba(175, 255, 100, 0.3);
}

.vitals { width: 164px; display: flex; flex-direction: column; gap: 5px; }
.vital-row { display: flex; align-items: center; gap: 7px; }
.vital-icon { width: 12px; font-size: 10px; color: var(--pink); text-align: center; }
.vital-icon.shield { color: var(--cyan); }
.vital-track { flex: 1; height: 5px; background: rgba(6, 8, 18, 0.6); border: 1px solid rgba(255, 240, 219, 0.13); transform: skew(-12deg); overflow: hidden; }
.vital-fill { height: 100%; width: 100%; transition: width 0.24s ease; }
.vital-fill.health { background: linear-gradient(90deg, #ff2f86, #ff7d4e); box-shadow: 0 0 9px rgba(255, 60, 130, 0.4); }
.vital-fill.armor { background: linear-gradient(90deg, #1e9bc0, #4ceaff); box-shadow: 0 0 9px rgba(50, 220, 255, 0.34); }

.hud-bottom-left {
  position: absolute;
  left: calc(28px + var(--safe-left));
  bottom: calc(27px + var(--safe-bottom));
}

.minimap-shell {
  position: relative;
  width: 208px;
  height: 208px;
  border: 1px solid rgba(255, 241, 220, 0.34);
  background: #101526;
  overflow: hidden;
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
  box-shadow: 0 12px 45px rgba(0, 0, 0, 0.35), inset 0 0 30px rgba(0, 0, 0, 0.4);
}

#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: 7px; border: 1px solid rgba(255, 238, 212, 0.13); clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); pointer-events: none; }
.compass { position: absolute; top: 7px; left: 50%; transform: translateX(-50%); color: var(--orange); font-size: 9px; font-weight: 700; letter-spacing: 0.15em; }
.compass span { display: inline-block; border-bottom: 3px solid var(--orange); padding: 0 4px 1px; }
.minimap-label { position: absolute; left: 12px; bottom: 10px; font-size: 8px; font-weight: 700; letter-spacing: 0.2em; color: rgba(255, 239, 220, 0.68); text-shadow: 0 1px 5px #000; }

.street-name { display: flex; align-items: center; gap: 8px; margin-top: 9px; font-size: 9px; letter-spacing: 0.2em; color: rgba(255, 239, 219, 0.6); font-weight: 700; }
.street-rule { display: block; width: 20px; height: 1px; background: var(--orange); }

.hud-bottom-right {
  position: absolute;
  right: calc(30px + var(--safe-right));
  bottom: calc(28px + var(--safe-bottom));
}

.weapon-card {
  display: grid;
  grid-template-columns: 94px 1fr;
  grid-template-rows: auto auto;
  column-gap: 11px;
  align-items: center;
  min-width: 225px;
  padding: 10px 12px 8px;
  background: linear-gradient(270deg, rgba(10, 9, 22, 0.78), rgba(10, 9, 22, 0.28));
  border-right: 2px solid rgba(255, 241, 220, 0.62);
  clip-path: polygon(12px 0, 100% 0, 100% 100%, 0 100%, 0 12px);
}

.weapon-silhouette { grid-row: 1 / 3; opacity: 0.88; }
.weapon-silhouette svg { display: block; width: 94px; fill: rgba(255, 239, 220, 0.8); filter: drop-shadow(0 0 8px rgba(255, 174, 95, 0.16)); }
.weapon-copy { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.05; }
.weapon-name { font-size: 9px; letter-spacing: 0.19em; color: rgba(255, 228, 196, 0.62); font-weight: 700; }
.weapon-ammo { font-family: "Bebas Neue", sans-serif; font-size: 25px; letter-spacing: 0.06em; color: #fff4e5; }
.reload-track { grid-column: 2; width: 100%; height: 2px; margin-top: 4px; background: rgba(255, 255, 255, 0.12); }
#reload-fill { height: 100%; width: 100%; background: var(--orange); transition: width 0.1s linear; }

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 24px;
  height: 24px;
  transform: translate(-50%, -50%);
  opacity: 0.78;
  transition: opacity 0.2s;
}
.crosshair i { position: absolute; display: block; background: rgba(255, 246, 232, 0.9); box-shadow: 0 0 5px rgba(0, 0, 0, 0.6); }
.crosshair .ch-t { left: 11px; top: 0; width: 1px; height: 6px; }
.crosshair .ch-b { left: 11px; bottom: 0; width: 1px; height: 6px; }
.crosshair .ch-l { top: 11px; left: 0; height: 1px; width: 6px; }
.crosshair .ch-r { top: 11px; right: 0; height: 1px; width: 6px; }
.crosshair span { position: absolute; left: 10.5px; top: 10.5px; width: 3px; height: 3px; border-radius: 50%; background: var(--orange); }
.crosshair.is-hit i { background: var(--pink); }
.crosshair.is-firing { opacity: 1; transform: translate(-50%, -50%) scale(1.28); }

.prompt {
  position: absolute;
  left: 50%;
  bottom: calc(90px + var(--safe-bottom));
  transform: translateX(-50%) translateY(8px);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 15px 9px;
  background: rgba(9, 9, 18, 0.78);
  border: 1px solid rgba(255, 239, 219, 0.2);
  backdrop-filter: blur(6px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}
.prompt.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.prompt-key { display: grid; place-items: center; width: 23px; height: 23px; border: 1px solid rgba(255, 239, 219, 0.6); font-size: 11px; font-weight: 700; color: var(--orange); }
.prompt-text { font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; }
.prompt-progress { position: absolute; left: 0; bottom: -1px; width: 100%; height: 2px; background: transparent; }
#prompt-progress-fill { height: 100%; width: 0%; background: var(--orange); box-shadow: 0 0 10px var(--orange); }

.heat-banner {
  position: absolute;
  top: calc(94px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}
.heat-banner.show { opacity: 1; }
.heat-kicker { color: var(--pink); font-size: 10px; font-weight: 700; letter-spacing: 0.26em; text-shadow: 0 0 14px rgba(255, 47, 134, 0.5); }
.heat-time { font-family: "Bebas Neue", sans-serif; font-size: 35px; letter-spacing: 0.08em; color: #fff1de; line-height: 0.95; }
.heat-hint { font-size: 9px; letter-spacing: 0.12em; color: rgba(255, 235, 213, 0.58); }

.toast {
  position: absolute;
  left: 50%;
  top: 31%;
  transform: translate(-50%, -50%) scale(0.96);
  padding: 11px 22px;
  border-left: 2px solid var(--orange);
  border-right: 2px solid var(--orange);
  background: rgba(8, 9, 18, 0.62);
  font-family: "Bebas Neue", sans-serif;
  font-size: 21px;
  letter-spacing: 0.09em;
  color: #fff3e2;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  text-align: center;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }

/* ============ START SCREEN ============ */

.start-screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  background:
    linear-gradient(90deg, rgba(7, 7, 16, 0.94) 0%, rgba(7, 7, 16, 0.8) 29%, rgba(7, 7, 16, 0.12) 64%, rgba(7, 7, 16, 0.28) 100%),
    linear-gradient(180deg, rgba(7, 7, 16, 0.38), transparent 30%, transparent 70%, rgba(7, 7, 16, 0.64));
  transition: opacity 0.65s ease, visibility 0.65s;
}

.start-screen.is-gone { opacity: 0; visibility: hidden; pointer-events: none; }

.start-grain {
  position: absolute;
  inset: 0;
  opacity: 0.08;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.7'/%3E%3C/svg%3E");
  mix-blend-mode: screen;
  pointer-events: none;
}

.start-content {
  position: absolute;
  left: clamp(28px, 8vw, 132px);
  top: 50%;
  transform: translateY(-50%);
  width: min(520px, 48vw);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 18px;
  color: var(--orange);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.25em;
  white-space: nowrap;
}
.eyebrow-rule { display: block; width: 42px; height: 1px; background: var(--orange); box-shadow: 0 0 8px rgba(255, 138, 61, 0.5); }
.eyebrow-rule.short { width: 16px; opacity: 0.5; }

.title {
  margin: 0;
  display: flex;
  flex-direction: column;
  font-family: "Bebas Neue", sans-serif;
  font-size: clamp(76px, 10.2vw, 154px);
  line-height: 0.75;
  letter-spacing: 0.015em;
  font-weight: 400;
  color: #fff4e4;
  text-shadow: 0 4px 40px rgba(0, 0, 0, 0.55);
}
.title-sunset { transform: translateX(-2px); }
.title-heist {
  margin-top: 0.12em;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--orange);
  text-shadow: 0 0 32px rgba(255, 94, 46, 0.28);
  letter-spacing: 0.065em;
  transform: translateX(3px);
}

.tagline {
  margin: 24px 0 0;
  color: rgba(255, 238, 217, 0.85);
  font-size: 14px;
  line-height: 1.45;
  letter-spacing: 0.08em;
  font-weight: 600;
}
.tagline span { color: rgba(255, 211, 90, 0.9); }

.start-job {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(390px, 100%);
  margin-top: 24px;
  padding: 12px 0 12px 14px;
  border-left: 2px solid var(--gold);
  background: linear-gradient(90deg, rgba(255, 211, 90, 0.08), transparent);
}
.start-job-left { display: flex; flex-direction: column; gap: 2px; }
.start-job-kicker { font-size: 8px; letter-spacing: 0.24em; color: var(--gold); font-weight: 700; }
.start-job strong { font-family: "Bebas Neue", sans-serif; font-size: 23px; letter-spacing: 0.06em; line-height: 1; color: #fff5e5; font-weight: 400; }
.start-job-left span:last-child { font-size: 10px; letter-spacing: 0.08em; color: rgba(255, 238, 215, 0.58); }
.start-job-reward { display: flex; flex-direction: column; align-items: center; padding: 0 15px; border-left: 1px solid rgba(255, 238, 215, 0.14); }
.start-job-reward span { font-size: 7px; letter-spacing: 0.2em; color: rgba(255, 238, 215, 0.48); }
.start-job-reward b { color: var(--pink); font-size: 19px; line-height: 1; text-shadow: 0 0 12px rgba(255, 47, 134, 0.45); }

#start-btn {
  appearance: none;
  margin-top: 22px;
  min-width: 210px;
  padding: 15px 34px 14px;
  border: 0;
  background: linear-gradient(100deg, var(--orange-hot), var(--orange) 58%, #ffc05c);
  color: #180b08;
  font-family: "Bebas Neue", sans-serif;
  font-size: 29px;
  letter-spacing: 0.2em;
  line-height: 1;
  cursor: pointer;
  clip-path: polygon(0 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
  box-shadow: 0 0 38px rgba(255, 96, 46, 0.34);
  transition: transform 0.16s, filter 0.16s;
  pointer-events: auto;
}
#start-btn:hover { transform: translateX(5px); filter: brightness(1.12); }
#start-btn:active { transform: translateX(2px) scale(0.99); }

.start-hints {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 22px;
  color: rgba(255, 236, 216, 0.5);
  font-size: 8px;
  letter-spacing: 0.15em;
  font-weight: 700;
}
.start-hints b { color: rgba(255, 243, 228, 0.9); font-weight: 700; }
.start-foot { margin-top: 11px; color: rgba(255, 218, 178, 0.46); font-size: 9px; letter-spacing: 0.1em; }

.start-right {
  position: absolute;
  right: clamp(22px, 4vw, 62px);
  bottom: calc(31px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  color: rgba(255, 237, 216, 0.65);
}
.start-stat { display: flex; align-items: baseline; gap: 10px; font-size: 8px; letter-spacing: 0.2em; }
.start-stat span { color: rgba(255, 237, 216, 0.35); }
.start-stat b { font-family: "Bebas Neue", sans-serif; font-size: 18px; letter-spacing: 0.08em; color: #fff2df; font-weight: 400; }
.start-stat b.hot { color: var(--pink); }
.start-version { margin-top: 11px; font-size: 7px; letter-spacing: 0.19em; color: rgba(255, 238, 218, 0.3); }

/* ============ LOADING / MODALS ============ */

.loading {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 17px;
  background: #080912;
  transition: opacity 0.6s ease, visibility 0.6s;
}
.loading.is-gone { opacity: 0; visibility: hidden; pointer-events: none; }
.loading-mark { font-family: "Bebas Neue", sans-serif; font-size: 72px; line-height: 1; color: var(--orange); text-shadow: 0 0 40px rgba(255, 94, 46, 0.45); transform: skew(-8deg); }
.loading-bar { width: 190px; height: 2px; background: rgba(255, 239, 219, 0.13); overflow: hidden; }
.loading-bar i { display: block; width: 42%; height: 100%; background: var(--orange); animation: loadbar 1.1s ease-in-out infinite; }
@keyframes loadbar { 0% { transform: translateX(-120%); } 100% { transform: translateX(400%); } }
.loading-text { font-size: 8px; letter-spacing: 0.28em; color: rgba(255, 231, 205, 0.45); }

.wasted,
.job-complete,
.final-screen {
  position: absolute;
  inset: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.35s ease, visibility 0.35s;
}
.wasted.show,
.job-complete.show,
.final-screen.show { opacity: 1; visibility: visible; }

.wasted { background: radial-gradient(circle, rgba(100, 0, 24, 0.28), rgba(5, 4, 10, 0.87)); }
.wasted-kicker { color: rgba(255, 80, 118, 0.7); font-size: 9px; letter-spacing: 0.3em; }
.wasted-title { font-family: "Bebas Neue", sans-serif; font-size: clamp(90px, 15vw, 190px); line-height: 0.85; color: #ff3d74; text-shadow: 0 0 60px rgba(255, 22, 84, 0.48); letter-spacing: 0.08em; }
.wasted-sub { color: rgba(255, 225, 215, 0.5); font-size: 10px; letter-spacing: 0.16em; }

.job-complete { background: linear-gradient(180deg, rgba(5, 6, 13, 0.2), rgba(5, 6, 13, 0.6)); }
.complete-kicker { color: var(--gold); font-size: 10px; letter-spacing: 0.34em; }
.complete-title { margin-top: 7px; font-family: "Bebas Neue", sans-serif; font-size: clamp(60px, 8vw, 112px); line-height: 0.88; letter-spacing: 0.06em; color: #fff3e1; text-shadow: 0 0 50px rgba(255, 184, 73, 0.2); }
.complete-cash { margin-top: 12px; font-family: "Bebas Neue", sans-serif; font-size: 41px; letter-spacing: 0.08em; color: var(--lime); text-shadow: 0 0 25px rgba(170, 255, 90, 0.35); }
.complete-sub { margin-top: 3px; color: rgba(255, 234, 209, 0.58); font-size: 10px; letter-spacing: 0.18em; }

.final-screen { background: radial-gradient(circle at 50% 55%, rgba(255, 101, 44, 0.18), rgba(4, 5, 12, 0.92) 64%); pointer-events: auto; }
.final-kicker { color: var(--orange); font-size: 10px; letter-spacing: 0.34em; }
.final-title { margin-top: 8px; font-family: "Bebas Neue", sans-serif; font-size: clamp(90px, 14vw, 180px); line-height: 0.72; text-align: center; letter-spacing: 0.03em; color: #fff1de; }
.final-title span { color: transparent; -webkit-text-stroke: 1px var(--orange); }
.final-copy { margin-top: 22px; text-align: center; color: rgba(255, 232, 208, 0.68); font-size: 12px; line-height: 1.5; letter-spacing: 0.1em; }
#restart-btn { appearance: none; margin-top: 24px; padding: 12px 30px; border: 1px solid rgba(255, 226, 194, 0.55); background: transparent; color: #fff1de; font-family: "Bebas Neue", sans-serif; font-size: 23px; letter-spacing: 0.18em; cursor: pointer; }
#restart-btn:hover { background: rgba(255, 138, 61, 0.15); }

/* ============ TOUCH ============ */

.touch-controls { display: none; }

@media (pointer: coarse), (max-width: 900px) {
  .touch-controls {
    display: block;
    position: absolute;
    inset: 0;
    z-index: 9;
    pointer-events: none;
  }
  .joystick-zone {
    position: absolute;
    left: calc(19px + var(--safe-left));
    bottom: calc(24px + var(--safe-bottom));
    width: 132px;
    height: 132px;
    pointer-events: auto;
    touch-action: none;
  }
  .joystick-base {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 1px solid rgba(255, 241, 220, 0.26);
    background: radial-gradient(circle, rgba(13, 15, 28, 0.42), rgba(13, 15, 28, 0.14));
    box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.2);
  }
  .joystick-knob {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 54px;
    height: 54px;
    margin: -27px;
    border-radius: 50%;
    border: 1px solid rgba(255, 160, 98, 0.7);
    background: rgba(255, 120, 55, 0.18);
    box-shadow: 0 0 22px rgba(255, 107, 45, 0.16);
    transform: translate(0, 0);
  }
  .touch-look { position: absolute; inset: 0 0 0 40%; pointer-events: auto; touch-action: none; }
  .touch-buttons {
    position: absolute;
    right: calc(18px + var(--safe-right));
    bottom: calc(22px + var(--safe-bottom));
    width: 168px;
    height: 178px;
    pointer-events: none;
  }
  .touch-btn {
    position: absolute;
    appearance: none;
    border-radius: 50%;
    border: 1px solid rgba(255, 238, 218, 0.32);
    background: rgba(12, 12, 24, 0.5);
    color: rgba(255, 241, 226, 0.92);
    font-family: "Bebas Neue", sans-serif;
    font-size: 18px;
    letter-spacing: 0.04em;
    pointer-events: auto;
    touch-action: none;
    backdrop-filter: blur(4px);
  }
  .touch-btn:active { background: rgba(255, 105, 45, 0.3); border-color: var(--orange); }
  .touch-btn.fire { width: 76px; height: 76px; right: 0; bottom: 44px; color: #1a0a06; background: linear-gradient(135deg, var(--orange-hot), var(--orange)); border: 0; box-shadow: 0 0 30px rgba(255, 87, 38, 0.32); font-size: 21px; }
  .touch-btn.action { width: 51px; height: 51px; right: 83px; bottom: 110px; color: var(--gold); border-color: rgba(255, 211, 90, 0.5); }
  .touch-btn.jump { width: 48px; height: 48px; right: 90px; bottom: 14px; font-size: 22px; }
  .touch-btn.run { width: 52px; height: 52px; right: 8px; bottom: 132px; font-size: 12px; }
  .touch-btn.drive { display: none; width: 48px; height: 48px; left: 50%; bottom: calc(36px + var(--safe-bottom)); transform: translateX(-50%); }
  .touch-btn.drive.show { display: grid; place-items: center; }
  .hud-bottom-left { left: calc(17px + var(--safe-left)); bottom: calc(172px + var(--safe-bottom)); }
  .minimap-shell { width: 142px; height: 142px; }
  .street-name { display: none; }
  .hud-bottom-right { right: calc(18px + var(--safe-right)); bottom: calc(214px + var(--safe-bottom)); }
  .weapon-card { min-width: 0; width: 153px; grid-template-columns: 0 1fr; padding: 7px 9px; }
  .weapon-silhouette { display: none; }
  .weapon-copy { align-items: flex-end; }
  .weapon-name { font-size: 7px; }
  .weapon-ammo { font-size: 19px; }
  .hud-top-left { top: calc(14px + var(--safe-top)); left: calc(14px + var(--safe-left)); gap: 10px; }
  .brand-small { display: none; }
  .mission-card { width: 225px; padding: 9px 10px 8px; }
  .mission-title { font-size: 19px; }
  .mission-objective { font-size: 10px; }
  .mission-meta { font-size: 8px; margin-top: 5px; }
  .hud-top-right { top: calc(14px + var(--safe-top)); right: calc(13px + var(--safe-right)); }
  .cash { gap: 5px; padding-left: 0; }
  .cash-label { display: none; }
  .cash-value { font-size: 25px; }
  .vitals { width: 111px; }
  .vital-icon { display: none; }
  .hud-top-center { top: calc(88px + var(--safe-top)); }
  .wanted { font-size: 14px; }
  .district { display: none; }
  .prompt { bottom: calc(128px + var(--safe-bottom)); max-width: 72vw; padding: 7px 11px; }
  .prompt-text { font-size: 9px; }
  .heat-banner { top: calc(124px + var(--safe-top)); }
  .heat-time { font-size: 28px; }
  .crosshair { display: none; }
  .start-content { width: min(430px, 72vw); left: 24px; }
  .title { font-size: clamp(70px, 19vw, 112px); }
  .eyebrow { font-size: 7px; letter-spacing: 0.16em; }
  .start-right { display: none; }
  .start-hints { gap: 9px; font-size: 7px; }
  .start-hints span:nth-child(n+3) { display: none; }
  .start-foot { display: none; }
  .start-job { margin-top: 17px; width: 100%; }
  .tagline { margin-top: 18px; font-size: 12px; }
  #start-btn { margin-top: 18px; padding: 13px 28px; font-size: 25px; }
}

@media (max-width: 560px) {
  .start-content { top: 46%; width: calc(100vw - 48px); }
  .title { font-size: clamp(66px, 21vw, 104px); }
  .start-job { width: 100%; }
  .start-hints { max-width: 260px; }
  .mission-card { width: 205px; }
  .hud-top-center { top: calc(84px + var(--safe-top)); }
}

@media (max-height: 560px) and (pointer: coarse) {
  .start-content { top: 50%; transform: translateY(-50%) scale(0.83); transform-origin: left center; }
  .start-job, .start-hints, .start-foot { display: none; }
  .minimap-shell { width: 118px; height: 118px; }
  .hud-bottom-left { bottom: calc(160px + var(--safe-bottom)); }
}

import "./style.css";
import * as THREE from "three";

/* ---------------------------------------------------------------------------
   SUNSET HEIST
   A self-contained open-world city game. All geometry, textures and audio are
   generated procedurally — no external assets beyond the bundled fonts.
--------------------------------------------------------------------------- */

const $ = (id) => document.getElementById(id);

const dom = {
  canvas: $("game-canvas"),
  hud: $("hud"),
  start: $("start-screen"),
  startBtn: $("start-btn"),
  restartBtn: $("restart-btn"),
  loading: $("loading"),
