  const shoes = new THREE.MeshStandardMaterial({ color: opts.shoes ?? 0x171820, roughness: 0.7 });
  const hairMat = new THREE.MeshStandardMaterial({ color: opts.hair ?? 0x17131a, roughness: 0.9 });

