    m.diamond.position.y = 3.1 + Math.sin(t * 2.2 + i) * 0.22;
    m.halo.position.y = m.diamond.position.y;
    const pulse = 0.5 + Math.sin(t * 3 + i) * 0.12;
    m.disc.material.opacity = active ? pulse * 0.42 : 0.08;
