/* ------------------------------------------------------------------ driving */
function findNearestCar() {
  let best = null;
  let bestD = 5.0;
  for (const car of cars) {
    if (car === game.driving) continue;
    const d = dist2(car.root.position.x, car.root.position.z, game.pos.x, game.pos.z);
    if (d < bestD) {
      bestD = d;
      best = car;
    }
