  g.beginPath();
  g.moveTo(0, -11);
  g.lineTo(7.5, 8);
  g.lineTo(0, 4.5);
  g.lineTo(-7.5, 8);
  g.closePath();
  g.fillStyle = game.driving ? "#ff8a3d" : "#fff1dd";
  g.fill();
  g.strokeStyle = "rgba(10,10,20,0.75)";
  g.lineWidth = 2;
  g.stroke();
