import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({
  channel: 'chromium',
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(`PAGEERROR: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`CONSOLE: ${m.text()}`); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__SUNSET__?.ready === true, { timeout: 30000 });
await page.waitForTimeout(400);
await page.click('#start-btn');
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/opencode/initial.png' });
console.log('state', await page.evaluate(() => ({ stage: window.__SUNSET__.state.stage, pos: { ...window.__SUNSET__.state.pos }, heading: window.__SUNSET__.state.heading, prompt: document.querySelector('#prompt-text').textContent, promptShown: document.querySelector('#prompt').classList.contains('show') })));
console.log('errors', errors);
await browser.close();

content.text:
New view: much better storefront. But issues:
- Sign "LIQUOR" huge and clipping top; we're too close (5m) to see the sign at y=7.4. The top shows sign text cropped. It's okay, but the huge pink horizontal awning at y=3.35 across the center (red bar) blocks view. The awning is a solid red/pink box 2.8 x 0.24 x 7 at x=-82.2, y=3.35, centered z=67, spanning z 63.5..70.5. From this view, it's a horizontal bar across the storefront. It looks odd, like a giant red beam. The door is pink. The marker beam is huge yellow rectangle (cylindrical billboard?) - looks like a big yellow transparent rectangle behind the character, due to the beam cylinder. It's okay but a bit much. The label is hidden (good). The toast at top center "MEET THE MARKER — 5 M" overlaps the LIQUOR sign. The HUD mission card says "Drive to the liquor store" but distance 5m. Should say "Start the heist at the marker" when within 5.2. It's not within due to exact 5.2. Fix spawn to 5.0.

- The storefront windows are dark brown/black and very large; they look like blank panels. Could make them glow warm with visible interior. Add a warm emissive panel with mullions and maybe a lit interior texture. Currently glassMat color 0x142a30 with emissive 0x2c1508 intensity 0.9; under tone mapping it appears dark brown. We can increase emissive to a warm amber, use MeshBasicMaterial? Better make windows look like lit shop windows: MeshBasicMaterial color 0x3a2a1a with map of warm gradient? Let's use a canvas texture with warm interior shapes. But maybe simpler: set glassMat to MeshStandardMaterial with color 0x2a1c12, emissive 0xffa34d, emissiveIntensity 0.35, roughness 0.2, metalness 0.4. That would glow warm. Or MeshBasicMaterial color 0xffb066, transparent opacity 0.35, blending additive? That could look like glowing windows. Add dark frames. We want "LIQUOR" store with lit windows. Use MeshBasicMaterial with color 0xffb56a, transparent true, opacity 0.45, toneMapped false? Might be too bright. Let's make two-layer: a dark glass plane plus an additive warm spill plane. Currently spill opacity 0.12 pink. Increase to 0.3 and use warm amber, and add interior silhouettes (shelves) via a canvas texture. Hmm.

- The car on right is huge and clipped, parked in road. It's at -89,74.5, 7.5m south. It appears on right. Fine, but it's very close and large. Could move it further to z=78 or x=-86? Actually if looking east, right side is +z, so car at z=74.5 is right. Move to z=78 (11m away) so less dominant, or x=-86.5 near curb. Let's put starter at (-86.5, 0.09, 78) heading π. That's 12m away, visible down the street to the right. But road x=-86.5, near curb -84, okay. This is on the east side of the road near building; car may be partly on sidewalk but fine. Could set heading 0 (south). Parked along curb. Good.

- The minimap is large and player arrow at bottom? Fine.

- The HUD mission card says "5 M" and "Drive to the liquor store" while on foot at marker. Fix spawn.

- The city looks blocky and the wall above is plain with windows (actually visible windows now, good). The sign is too high/large; maybe lower the sign to y=6.2 and reduce size to 6.4x2.0. At 5m, top of sign at y 7.2, camera y ~2.4, vertical angle 45°, still clipped. Lower to y=5.6, height 1.9 -> top 6.55, angle 40°. Still clipped top. But the player can see it when backing up. At spawn, maybe we don't need to see the whole sign. But the top clipped text is ugly. Could move spawn back to x=-91 (7m) and marker at -83.8, distance 7.2 > 5.2, so prompt not shown. We want prompt shown. Could increase interaction radius to 7.5m. Then spawn at -91, distance 7.2, prompt shows, and sign is more visible. Camera at -98, distance to wall 17m. The sign top angle from camera y ~3.5: (7.4-3.5)/17 = 13°, not clipped. That's much better. Let's set spawn -91, interaction radius 7.5 (or 8). But then startHeist from 7.2m; guards at -85.6..-86.8, 4-5m ahead. Fine. Player can press E at spawn. The marker ring is 7m away, not huge. The beam still large but okay.

Actually the camera is behind the player by 7m; distance from camera to wall = 17m. The sign at y 7.4, camera y ~? Player y 1.5 target, pitch 0.18, camera y = 1.5 + sin(0.18)*7 +1 = 3.75. Top of sign at 8.55 (center 7.4 +1.15) => 4.8/17 = 15.7°, within vertical half-FOV 31°. So fully visible. Great.

So set SPAWN x=-91, keep marker -83.8 (7.2m). Change interaction radius from 5.2 to 7.6 in updateInteraction and handleInteract, and updateMissionUI threshold. But objective says "Start the heist at the marker" when d<5.2; change to <7.6. However, at 7.2m, prompt shows "Start heist". Good. Maybe 7.5m is a bit far to start, but okay for UX. Or spawn at -90.5 (6.7m) and radius 7.0. Let's do spawn -90.5, radius 7.2. Distance 6.7. Camera at -97.5, wall 16.5m. Good. Sign fully visible. Player car at z=78.

- The marker beam yellow rectangle: it's actually a cylinder with additive material, but because it's open-ended and viewed from side, looks like a big translucent yellow rectangle. It's fine but maybe reduce radius from 2.4-2.8 to 1.8-2.2 and opacity 0.1. The ring radius 2.1 is large; at 6.7m it appears 2.1*? okay. Reduce beam radius to 1.9/2.2 and height 6.5. Also maybe reduce disc. Not critical.

- The awning bar across the facade is ugly. It's a solid box 2.8 x 0.24 x 7 at y=3.35. It appears as a giant pink bar. Change its material to a darker color and make it a thin canopy with vertical supports? Or lower opacity. Use color from heist.color with roughness, but it's fully lit. Could make it dark charcoal with a pink underside neon strip. Use `new THREE.MeshStandardMaterial({ color: 0x241824, roughness: 0.75 })` and add a thin neon strip underneath (BoxGeometry(0.08,0.04,6.8) MeshBasicMaterial heist.color) at y=3.2. That will look like a canopy with neon edge, not a solid pink bar. Good.

- The windows: make them warm and add interior shelves. Let's create a canvas texture function `makeStorefrontTexture(color)` returning a texture with warm gradient, dark shelf lines, bottles maybe. Then use MeshBasicMaterial map with toneMapped false? Actually a basic material with a map will show the texture exactly; with tone mapping disabled maybe too bright, but can set toneMapped true. Use MeshStandardMaterial with map + emissiveMap? Simpler: MeshBasicMaterial({ map: tex, toneMapped: true }) and color 0xffffff. It will be unlit and show warm interior. But it may look flat; that's okay for a stylized game. We can create a 256x128 canvas with dark frame, warm gradient, shelves, and a few bottle silhouettes. Then 2 panels. That will be more interesting. Also add a glass reflection diagonal.

Let's implement `makeStorefrontTexture` near makeSignTexture. But maybe easier inline in addHeistVenue using canvas. We can define a global function before addHeistVenue. Need to be careful with draw. Let's write:

```
function makeStorefrontTexture(color) {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0,0,0,128);
  grad.addColorStop(0, '#2a160c');
  grad.addColorStop(0.45, '#5a2a12');
  grad.addColorStop(1, '#1a0d08');
  g.fillStyle = grad; g.fillRect(0,0,256,128);
  // warm light pools
  for (let i=0;i<3;i++) { const x=32+i*96; const rad=g.createRadialGradient(x,44,2,x,44,52); rad.addColorStop(0,'rgba(255,196,110,0.95)'); rad.addColorStop(1,'rgba(255,120,40,0)'); g.fillStyle=rad; g.fillRect(x-52,0,104,110); }
  // shelves
  g.fillStyle='rgba(20,10,6,0.85)';
  for (const y of [58,82,106]) g.fillRect(8,y,240,4);
  // bottles
  for (let i=0;i<24;i++) { const x=12+ (i%12)*20 + (i>11?10:0); const y= i>11?62:86; g.fillStyle = `rgba(${...})`; g.fillRect(x, y-14, 5, 14); g.fillRect(x+1, y-18, 3, 4); }
  // glass reflection
  g.fillStyle='rgba(180,230,255,0.08)';
  g.beginPath(); g.moveTo(0,0); g.lineTo(80,0); g.lineTo(20,128); g.lineTo(0,128); g.fill();
  const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace; return tex;
}
```
Then glassMat = MeshBasicMaterial({ map: tex, toneMapped: true }). Maybe add `transparent:false`. It will be emissive-like. Good. For panel plane geometry 5.4x2.45, aspect 2.2, texture 2:1, close. Add frames/mullions on top.

Could also add a third panel above the door? No.

- The sign "LIQUOR" is huge but okay. Maybe lower sign to y=6.3 and width 7.5. At 16m camera distance, sign top angle (6.3+1.15-3.75)/16.5 = 12.7°, fine. Even at y=7.4, 15.7°, fine. Keep.

