  if (heist.signSide === "west") awn.position.set(-heist.bw / 2 - 1.2, 3.35, 0);
  else if (heist.signSide === "east") awn.position.set(heist.bw / 2 + 1.2, 3.35, 0);
  else awn.position.set(0, 3.35, heist.bd / 2 + 1.2);
  g.add(awn);
  const awnGlow = new THREE.Mesh(
