    e.set(rr(-0.04, 0.04), rr(0, TAU), rr(-0.04, 0.04));
    q.setFromEuler(e);
    p.set(x, 0.1, z);
    s.set(scale, scale, scale);
    m.compose(p, q, s);
    trunks.setMatrixAt(i, m);

