import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({
  channel: 'chromium',
  headless: false,
  args: [
    '--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--enable-features=Vulkan',
    '--use-vulkan=swiftshader', '--disable-vulkan-surface',
    '--disable-background-timer-throttling', '--disable-renderer-backgrounding', '--disable-backgrounding-occluded-windows',
  ],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(`PAGEERROR: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`CONSOLE: ${m.text()}`); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__SUNSET__?.ready === true, { timeout: 30000 });
await page.bringToFront();
await page.waitForTimeout(400);
await page.click('#start-btn');
await page.waitForTimeout(800);

const snap = () => page.evaluate(() => {
  const s = window.__SUNSET__.state;
  return {
    stage: s.stage, pos: { x: +s.pos.x.toFixed(2), z: +s.pos.z.toFixed(2) }, health: Math.round(s.health),
    wanted: s.wanted, currentHeist: s.currentHeist, escapeTimer: +s.escapeTimer.toFixed(1),
    guards: window.__SUNSET__.guards.filter(g => g.alive).length,
    police: window.__SUNSET__.police.length, money: s.money,
    prompt: document.querySelector('#prompt-text').textContent,
    promptShown: document.querySelector('#prompt').classList.contains('show'),
    objective: document.querySelector('#mission-objective').textContent,
    safeVisible: window.__SUNSET__.markers[s.currentHeist].safe.visible,
    completeVisible: document.querySelector('#job-complete').classList.contains('show'),
    toast: document.querySelector('#toast-text').textContent,
  };
});
console.log('initial', await snap());

// Walk forward with real input, allowing for the software renderer's low fps.
await page.keyboard.down('w');
await page.waitForTimeout(2500);
await page.keyboard.up('w');
await page.waitForTimeout(300);
console.log('after walk', await snap());

// Start the heist.
await page.keyboard.press('e');
await page.waitForTimeout(700);
await page.evaluate(() => { const s = window.__SUNSET__.state; s.health = 1000; s.armor = 1000; });
console.log('combat', await snap());
await page.screenshot({ path: '/tmp/opencode/combat.png' });

async function centreOnGuard() {
  for (let i = 0; i < 12; i++) {
    const ndc = await page.evaluate(() => {
      const { guards, camera, THREE } = window.__SUNSET__;
      const g = guards.find(g => g.alive);
      if (!g) return null;
      const v = new THREE.Vector3(g.x, 1.2, g.z).project(camera);
      return { x: v.x, y: v.y, health: g.health };
    });
    if (!ndc) return null;
    if (Math.abs(ndc.x) < 0.03 && Math.abs(ndc.y) < 0.04) return ndc;
    await page.evaluate(({ dx, dy }) => {
      const { cam } = window.__SUNSET__;
      cam.yaw -= dx * 0.22;
      cam.pitch = Math.max(-0.08, Math.min(0.72, cam.pitch - dy * 0.06));
    }, { dx: ndc.x, dy: ndc.y });
    await page.waitForTimeout(180);
  }
  return null;
}

for (let round = 0; round < 16; round++) {
  const alive = await page.evaluate(() => window.__SUNSET__.guards.filter(g => g.alive).length);
  if (!alive) break;
  const centred = await centreOnGuard();
  if (!centred) break;
  await page.keyboard.press('f');
  await page.waitForTimeout(500);
}
await page.waitForTimeout(500);
console.log('after shooting', await snap());
await page.screenshot({ path: '/tmp/opencode/loot.png' });

// Move to the safe and crack it.
await page.evaluate(() => window.__SUNSET__.teleport(-84.5, 67));
await page.waitForTimeout(1200);
console.log('at safe', await snap());
await page.evaluate(() => { window.__SUNSET__.state.lootProgress = 0.97; });
await page.keyboard.down('e');
await page.waitForTimeout(2500);
await page.keyboard.up('e');
await page.waitForTimeout(700);
console.log('after loot', await snap());
await page.screenshot({ path: '/tmp/opencode/escape.png' });

// Escape the heat.
await page.evaluate(() => window.__SUNSET__.teleport(118, 118));
await page.waitForTimeout(1000);
await page.evaluate(() => { window.__SUNSET__.state.escapeTimer = 0.4; });
await page.waitForTimeout(2500);
console.log('complete', await snap());
await page.screenshot({ path: '/tmp/opencode/complete.png' });

// Next job unlock.
await page.evaluate(() => { window.__SUNSET__.state.completeTimer = 0.05; });
await page.waitForTimeout(1000);
console.log('next job', await snap());
await page.screenshot({ path: '/tmp/opencode/nextjob.png' });

// Second heist starts.
await page.evaluate(() => window.__SUNSET__.teleport(7.4, 22));
await page.waitForTimeout(1200);
console.log('at heist 2', await snap());
await page.keyboard.press('e');
await page.waitForTimeout(900);
console.log('heist 2 combat', await snap());
await page.screenshot({ path: '/tmp/opencode/heist2-start.png' });

console.log('errors', errors);
await browser.close();

